'use client';
import React,{useEffect,useState,useRef} from 'react';
import {RecordRow as R} from '@/lib/erp-primitives';
import {meetingElapsed,l10Agenda} from '@/lib/leadership';
type Act=(x:any)=>Promise<unknown>;
export function MeetingTimer({meeting,minutes,step,busy,dirty,act}:{meeting:R;minutes:number;step:string;busy:boolean;dirty:boolean;act:Act}){
 const [now,setNow]=useState(Date.now());useEffect(()=>{const id=setInterval(()=>setNow(Date.now()),1000);return()=>clearInterval(id)},[]);
 const v=meetingElapsed(meeting,now),seconds=Math.floor(v.byStep[step]||0),remaining=Math.max(0,minutes*60-seconds);const time=(n:number)=>Math.floor(n/60)+':'+String(n%60).padStart(2,'0');
 return <div className="l10timer"><strong>{time(remaining)}</strong><span>{seconds>=minutes*60?'Allocated time reached':minutes+' minute section'}</span><small>Meeting elapsed {time(Math.floor(v.total))}{meeting.status==='Completed'?' · Completed':meeting.status==='In progress'&&v.paused?' · Paused':''}</small>{meeting.status==='In progress'&&<button className="secondary" disabled={busy||dirty} onClick={()=>void act({action:'meeting_control',id:meeting.id,expectedVersion:meeting.version,command:v.paused||!v.tracked?'Resume':'Pause'})}>{v.paused||!v.tracked?'Resume meeting':'Pause meeting'}</button>}<small>{v.tracked?'Timer state is saved with this meeting.':'Timing begins when you start or resume this meeting.'}</small></div>;
}
export function QuickCapture({meeting,kind,seed={},act,busy,onDirty,onClose}:{meeting:R;kind:string;seed?:any;act:Act;busy:boolean;onDirty:(v:boolean)=>void;onClose:()=>void}){
 const [name,setName]=useState(seed.name||''),[owner,setOwner]=useState(seed.owner||''),[due,setDue]=useState(new Date(Date.parse(meeting.date+'T12:00:00Z')+7*86400000).toISOString().slice(0,10)),[details,setDetails]=useState(seed.identified||''),[priority,setPriority]=useState('Normal'),[error,setError]=useState('');
 const dirty=!!name||!!details||!!owner;useEffect(()=>{onDirty(dirty)},[dirty]);
 const title=kind==='task'?'To do':kind==='eos_issue'?'Issue':kind==='headlines'?'Headline':kind==='cascadingMessages'?'Message':'Note';
 async function submit(e:React.FormEvent){e.preventDefault();setError('');let input:any;
 if(['task','eos_issue'].includes(kind))input={action:'create',type:kind,company:meeting.company,...seed,name,owner,date:meeting.date,meetingId:meeting.id,...(kind==='task'?{eos:true,due,notes:details}:{priority,identified:details||name})};
 else {const text=[meeting[kind],name,details].filter(Boolean).join('\n');if(text.length>10000){setError('This meeting note is full. Shorten the existing notes before adding more.');return;}input={action:'edit',id:meeting.id,expectedVersion:meeting.version,fields:{[kind]:text}};}
 const saved=await act(input);if(saved===false){setError('Not saved. Review the workspace error and try again.');return;}onDirty(false);onClose();
 }
 return <form className="l10capture" onSubmit={submit}><header><h3>Quick capture · {title}</h3><small>{meeting.company} · This L10 meeting</small></header>{error&&<p role="alert">{error}</p>}<label>{['task','eos_issue'].includes(kind)?'Title':'Update'}<input disabled={busy} autoFocus required maxLength={500} value={name} onChange={e=>setName(e.target.value)}/></label>{['task','eos_issue'].includes(kind)&&<label>Owner<input disabled={busy} required maxLength={500} value={owner} onChange={e=>setOwner(e.target.value)}/></label>}{kind==='task'&&<label>Due date<input disabled={busy} type="date" required value={due} onChange={e=>setDue(e.target.value)}/></label>}{kind==='eos_issue'&&<label>Priority<select disabled={busy} value={priority} onChange={e=>setPriority(e.target.value)}>{['High','Normal','Low'].map(p=><option key={p}>{p}</option>)}</select></label>}<label>{kind==='eos_issue'?'What needs to be resolved?':'Details, optional'}<textarea disabled={busy} rows={3} maxLength={5000} value={details} onChange={e=>setDetails(e.target.value)}/></label><div className="sectiontoolbar"><button className="primary" disabled={busy}>Save {title.toLowerCase()}</button><button type="button" className="secondary" disabled={busy} onClick={()=>{if(dirty&&!window.confirm('Discard this unsaved capture?'))return;onDirty(false);onClose()}}>Cancel</button></div></form>;
}
export function InlineActual({record,act,busy,onDirty,onClose}:{record:R;act:Act;busy:boolean;onDirty:(v:boolean)=>void;onClose:()=>void}){
 const version=useRef(record.version),stale=record.version!==version.current;
 const [value,setValue]=useState(String(record.actual??'')),[error,setError]=useState('');const dirty=value!==String(record.actual??'');useEffect(()=>{onDirty(dirty||stale)},[dirty,stale]);
 return <form className="inlineactual" onSubmit={async e=>{e.preventDefault();setError('');const saved=await act({action:'edit',id:record.id,expectedVersion:version.current,fields:{actual:Number(value)}});if(saved===false){setError('Actual not saved. Review the workspace error.');return;}onDirty(false);onClose();}}><label>Actual for {record.name}<input disabled={busy} autoFocus type="number" min="0" step="any" required value={value} onChange={e=>setValue(e.target.value)}/></label><button className="primary" disabled={busy||!dirty||stale}>Save actual</button><button type="button" className="secondary" disabled={busy} onClick={()=>{if(dirty&&!window.confirm('Discard this actual?'))return;onDirty(false);onClose()}}>Cancel</button>{stale&&<p role="alert">This metric changed. Cancel and reopen it to review the latest actual.</p>}{error&&<p role="alert">{error}</p>}</form>;
}

export function MeetingAgenda({meeting,step,review,busy,navigate,next}:{meeting:R;step:string;review:any;busy:boolean;navigate:(s:string)=>void;next:()=>void}){
 const live=meeting.status==='In progress',complete=meeting.status==='Completed',index=l10Agenda.findIndex(a=>a.name===step),reviewed=meeting.l10Clock?.reviewedSteps||[];
 const counts:Record<string,string>={Scorecard:(review?.scorecards?.length||0)+' metrics','Rock review':(review?.rocks?.length||0)+' Rocks','To do review':(review?.todos?.filter((r:any)=>r.status!=='Done').length||0)+' open actions','Identify, discuss, solve':(review?.issues?.filter((r:any)=>!['Solved','Archived'].includes(r.status)).length||0)+' open issues'};
 return <nav aria-label={live?'Live meeting agenda':'Fixed L10 agenda'} className={live?'l10livemenu':''}><h3>{live?'Meeting agenda':'Fixed L10 agenda'}</h3>{live&&<div className="l10menuprogress" role="status"><strong>{meeting.l10Clock?.paused?'Meeting paused':'Meeting in progress'}</strong><span>Section {index+1} of 7 · {reviewed.length} reviewed</span><progress max={7} value={reviewed.length} aria-label="Reviewed agenda sections"/></div>}<ol>{l10Agenda.map((a,i)=>{const active=a.name===step,done=reviewed.includes(a.name),label=active?'Current section':done?'Reviewed':i===index+1?'Up next':'Not reviewed';return <li key={a.name} data-agenda-state={active?'current':done?'reviewed':'pending'}><button className={active?'primary':'secondary'} aria-current={active?'step':undefined} disabled={busy} onClick={()=>navigate(a.name)}><span>{done&&!active?'✓ ':''}{i+1}. {a.name}</span><small>{a.minutes} min{counts[a.name]?' · '+counts[a.name]:''}</small>{live&&<small className="l10stepstate">{label}</small>}</button></li>})}</ol>{live&&index<6&&<button className="primary l10advance" disabled={busy} onClick={next}>Finish section and continue</button>}{complete&&<small>Saved meeting agenda</small>}</nav>;
}
